import itertools

def solve():
    for C in range(1, 20):
        # Find all representations of C^2 as sum of 4 squares
        # a^2 + b^2 + c^2 + d^2 = C^2
        # We can assume 0 <= a <= b <= c <= d
        a_list = []
        C2 = C*C
        for a in range(C + 1):
            for b in range(a, C + 1):
                for c in range(b, C + 1):
                    d2 = C2 - a*a - b*b - c*c
                    if d2 < 0: break
                    d = int(d2**0.5)
                    if d*d == d2 and d >= c:
                        a_list.append((a, b, c, d))

        # Find all representations of 7*C^2 as sum of 4 squares
        b_list = []
        S2 = 7 * C2
        # Max possible value for b_i is sqrt(7*C^2) = C * sqrt(7)
        limit = int(S2**0.5)
        for a in range(limit + 1):
            for b in range(a, limit + 1):
                for c in range(b, limit + 1):
                    d2 = S2 - a*a - b*b - c*c
                    if d2 < 0: break
                    d = int(d2**0.5)
                    if d*d == d2 and d >= c:
                        b_list.append((a, b, c, d))

        # Now we need to check if we can assign signs and permutations to make them orthogonal
        # For each tuple in a_list and b_list, try all sign combinations and permutations.
        # However, that's too many. Let's optimize.
        # Instead of permutations, we can just iterate through permutations of a_list[i]
        # and sign changes of both.
        for a_tuple in a_list:
            for b_tuple in b_list:
                # Try all permutations of a_tuple
                for a_perm in itertools.permutations(a_tuple):
                    # Try all sign combinations for a_perm (2^4 = 16)
                    for a_signs in itertools.product([-1, 1], repeat=4):
                        a_vec = [s * v for s, v in zip(a_signs, a_perm)]
                        # Now we need to see if there's a signed permutation of b_tuple orthogonal to a_vec
                        # Instead of iterating all, we can just check all signed permutations of b_tuple
                        for b_perm in itertools.permutations(b_tuple):
                            for b_signs in itertools.product([-1, 1], repeat=4):
                                b_vec = [s * v for s, v in zip(b_signs, b_perm)]
                                if sum(av * bv for av, bv in zip(a_vec, b_vec)) == 0:
                                    return (a_vec, b_vec, C)
    return None

result = solve()
print(result)
